using System.Text.Json;
using Xunit;

namespace BritanniaRenaissance.Content.Tests;

/// <summary>
/// The greater-Britain spawn areas and wildlife (owner sign-off 2026-10-18, docs/Greater-Britain-Spawn-Areas-Evidence.md):
/// spawners graded by their most dangerous creature, danger rising in rings out from the Britain bank, one coherent theme per
/// area, wildlife through the forests, and single flavor objects scattered through each area. Generated by tools/spawn-design
/// (build_data.py for the spawners, place_flavor.py for the flavor objects).
/// </summary>
public class GreaterBritainSpawnAreasTests
{
    private static readonly string Root = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "data", "world-generation", "alpha2b");
    private const int BankX = 1470, BankY = 1620;

    // tier 3 and 4 (75+ hit points, or a hit of 15+, or the strong casters): never at Britain's doorstep
    private static readonly HashSet<string> Dangerous = new(StringComparer.Ordinal)
    {
        "Troll", "Ettin", "Ogre", "Gargoyle", "Gazer", "Corpser", "Reaper", "DireWolf", "GrizzlyBear",
        "SkeletalKnight", "BoneKnight", "Wisp", "OrcishMage", "WaterElemental", "Lich", "Mummy"
    };

    private static List<JsonElement> Spawners() =>
        JsonDocument.Parse(File.ReadAllText(Path.Combine(Root, "greater-britain-spawn-areas.json"))).RootElement.EnumerateArray().Select(e => e.Clone()).ToList();

    private static JsonElement Manifest() => JsonDocument.Parse(File.ReadAllText(Path.Combine(Root, "world-generation.json"))).RootElement;

    private static (int X, int Y) At(JsonElement s)
    {
        var l = s.GetProperty("location").EnumerateArray().Select(v => v.GetInt32()).ToArray();
        return (l[0], l[1]);
    }

    private static IEnumerable<string> Names(JsonElement s) => s.GetProperty("entries").EnumerateArray().Select(e => e.GetProperty("name").GetString()!);

    [Fact]
    public void ManifestListsTheAreasLast()
    {
        var spawnFiles = Manifest().GetProperty("customSpawnerFiles").EnumerateArray().Select(e => e.GetString()).ToList();
        // the last record per GUID wins, so the areas file must come after every file whose spawners it re-themes
        Assert.Equal("greater-britain-spawn-areas.json", spawnFiles[^1]);
    }

    [Fact]
    public void GuidsAndPlacesAreUniqueAndEveryRecordIsOnFelucca()
    {
        var all = Spawners();
        Assert.True(all.Count >= 100);
        Assert.Equal(all.Count, all.Select(s => s.GetProperty("guid").GetString()).Distinct(StringComparer.OrdinalIgnoreCase).Count());
        Assert.Equal(all.Count, all.Select(At).Distinct().Count());
        Assert.All(all, s => Assert.Equal("Felucca", s.GetProperty("map").GetString()));
    }

    [Fact]
    public void NoPostEraCreatureIsSpawned()
    {
        var excluded = Manifest().GetProperty("excludedSpawnerTypes").EnumerateArray().Select(e => e.GetString()!).ToHashSet(StringComparer.OrdinalIgnoreCase);
        Assert.All(Spawners(), s => Assert.DoesNotContain(Names(s), excluded.Contains));
    }

    [Fact]
    public void NothingDangerousSpawnsAtBritainsDoorstep()
    {
        // inside 300 tiles of the bank only beginner and step-up creatures (the owner's rings); Barrow Fields' step-up undead are within this too
        foreach (var s in Spawners())
        {
            var (x, y) = At(s);
            if (Math.Sqrt((x - BankX) * (x - BankX) + (y - BankY) * (y - BankY)) < 300)
            {
                Assert.DoesNotContain(Names(s), Dangerous.Contains);
            }
        }
    }

    [Fact]
    public void EveryCountCanBeFilled()
    {
        foreach (var s in Spawners())
        {
            Assert.True(s.GetProperty("entries").EnumerateArray().Sum(e => e.GetProperty("maxCount").GetInt32()) >= s.GetProperty("count").GetInt32());
        }
    }

    [Fact]
    public void FlavorObjectsAreMapStaticsSpreadOutNeverAPlayerItemAndNeverBlocking()
    {
        // owner, 2026-10-18: single standalone flavor pieces, never the art of something a player can own or pick up (feathers), drawn as
        // the map's own statics (no hover highlight), and never blocking a house; the full checks are tools/spawn-design/check_deco.py
        var manifest = Manifest();
        Assert.DoesNotContain("greater-britain-flavor.cfg", manifest.GetProperty("customDecorationFiles").EnumerateArray().Select(e => e.GetString()));
        Assert.Contains("greater-britain-flavor.cfg", manifest.GetProperty("retiredDecorationFiles").EnumerateArray().Select(e => e.GetString()));
        Assert.True(File.Exists(Path.Combine(Root, "retired", "greater-britain-flavor.cfg")));

        var playerItems = new HashSet<int> { 0x0DFA, 0x0DFB, 0x0A55, 0x0A56, 0x09A9, 0x0E3C, 0x1402, 0x1853, 0x0F36, 0x0ED4, 0x0ECA, 0x0ECB, 0x0ECC, 0x1AE0, 0x1AE2, 0x0F34, 0x0F3B, 0x1363, 0x1B09, 0x1B0A };
        // impassable art (rocks, the standalone gravestone, the egg case, one splintered wood) would block a house and the way
        var blocking = new HashSet<int> { 0x0C2D, 0x0ED5, 0x10D9, 0x1368, 0x1369, 0x136A, 0x136B, 0x136C };
        var patch = JsonDocument.Parse(File.ReadAllText(Path.Combine(Root, "..", "..", "map-patches", "greater-britain-flavor-statics.json"))).RootElement;
        Assert.Equal(0, patch.GetProperty("map").GetInt32());
        var placed = new List<(int X, int Y)>();
        foreach (var piece in patch.GetProperty("statics").EnumerateArray())
        {
            var v = piece.EnumerateArray().Select(e => e.GetInt32()).ToArray();
            Assert.True(v[0] < 0x2000, $"0x{v[0]:X4} is after the era");
            Assert.DoesNotContain(v[0], playerItems);
            Assert.DoesNotContain(v[0], blocking);
            Assert.InRange(v[1], 1000, 1999);
            Assert.InRange(v[2], 1250, 2049);
            placed.Add((v[1], v[2]));
        }

        Assert.InRange(placed.Count, 300, 700);
        // spread out: no two pieces closer than 10 tiles (14 between the first set; the colour pieces keep 10), so nothing reads as a composed group
        for (var i = 0; i < placed.Count; i++)
        {
            for (var j = i + 1; j < placed.Count; j++)
            {
                var dx = placed[i].X - placed[j].X;
                var dy = placed[i].Y - placed[j].Y;
                Assert.True(dx * dx + dy * dy >= 10 * 10, $"{placed[i]} and {placed[j]} are too close");
            }
        }
    }
}
